#include <array>
#include <limits>
#include <stdexcept>

#include "support.h"
#include "metrics/vmaf/v0/vmaf_v0_internal.h"

namespace {

using namespace vqm::internal;

// Inputs and final scores from the pinned libvmaf float v0.6.1 oracle: the
// four 64x48 frames generated by make_vmaf_fixtures.py, with each distorted
// luma scaled around 128 by 0.3, 0.45, 0.6, and 0.75 respectively.
struct OracleFrame {
    VmafV061Spatial spatial;
    double transition;
    double motion2;
    double score;
};
constexpr std::array<OracleFrame, 4> kFrames{{
    {{0.3646102461618792,
      {0.67127416280807639, 0.62432118758434552, 0.58644902383704134,
       0.52962018769656771}},
     0.0,
     0.0,
     0.0},
    {{0.49851355215890464,
      {0.77950838616346041, 0.75043530811766146, 0.72373043444243668,
       0.69393769630126623}},
     33.434216,
     29.808189392089844,
     9.813379604840847},
    {{0.63504848446359474,
      {0.8568640000533555, 0.84036787018088588, 0.82402837087070646,
       0.78887826775464709}},
     29.808189392089844,
     29.808189392089844,
     36.964203674503736},
    {{0.76957654068571957,
      {0.91743756978360436, 0.90977742985209298, 0.89989463144151871,
       0.88486503416526663}},
     33.892772674560547,
     33.892772674560547,
     72.649928458827034},
}};

void CheckFrame(const VmafV061Frame& frame, std::size_t index) {
    CHECK(frame.index == index);
    CHECK_NEAR(frame.features.motion2, kFrames[index].motion2, 1e-9);
    CHECK_NEAR(frame.features.adm2, kFrames[index].spatial.adm2, 0.0);
    CHECK_NEAR(frame.score, kFrames[index].score, 1e-9);
}

}  // namespace

VQM_TEST(TestVmafSequenceOracleAndBoundaries) {
    VmafV061Sequence sequence;
    CHECK_THROWS_AS(sequence.PooledScore(), std::logic_error);
    auto frame = sequence.Push(kFrames[0].spatial, kFrames[0].transition);
    CHECK(frame.has_value());
    if (frame) CheckFrame(*frame, 0);
    CHECK(!sequence.Push(kFrames[1].spatial, kFrames[1].transition));
    frame = sequence.Push(kFrames[2].spatial, kFrames[2].transition);
    CHECK(frame.has_value());
    if (frame) CheckFrame(*frame, 1);
    frame = sequence.Push(kFrames[3].spatial, kFrames[3].transition);
    CHECK(frame.has_value());
    if (frame) CheckFrame(*frame, 2);
    frame = sequence.Flush();
    CHECK(frame.has_value());
    if (frame) CheckFrame(*frame, 3);
    CHECK(!sequence.Flush());
    const auto pooled = sequence.PooledScore();
    CHECK(pooled.has_value());
    if (pooled) CHECK_NEAR(*pooled, 29.856877934542904, 1e-9);
    CHECK_THROWS_AS(sequence.Push(kFrames[0].spatial, 0.0), std::logic_error);

    sequence.Reset();
    CHECK(sequence.Push(kFrames[0].spatial, 0.0).has_value());
    CHECK(!sequence.Flush());
    const auto single_score = sequence.PooledScore();
    CHECK(single_score.has_value());
    if (single_score) CHECK_NEAR(*single_score, 0.0, 0.0);
    sequence.Reset();
    CHECK(!sequence.Flush());
    CHECK(!sequence.PooledScore());
}

VQM_TEST(TestVmafSequenceInvalidInputDoesNotAdvance) {
    VmafV061Sequence sequence;
    auto invalid = kFrames[0].spatial;
    invalid.vif[2] = std::numeric_limits<double>::quiet_NaN();
    CHECK_THROWS_AS(sequence.Push(invalid, 0.0), std::invalid_argument);
    CHECK_THROWS_AS(
        sequence.Push(kFrames[0].spatial, 1.0), std::invalid_argument
    );
    const auto first = sequence.Push(kFrames[0].spatial, 0.0);
    CHECK(first && first->index == 0);
    CHECK_THROWS_AS(
        sequence.Push(kFrames[1].spatial, -1.0), std::invalid_argument
    );
    CHECK(!sequence.Push(kFrames[1].spatial, kFrames[1].transition));
    const auto last = sequence.Flush();
    CHECK(last && last->index == 1);
}

VQM_TEST(TestVmafSequenceWithoutTemporalWeighting) {
    VmafV061Sequence sequence(false, true, vqm::VmafModel::Standard1080, false);
    double expected_sum = 0.0;
    for (std::size_t i = 0; i < kFrames.size(); ++i) {
        const auto frame =
            sequence.Push(kFrames[i].spatial, kFrames[i].transition);
        CHECK(frame.has_value());
        if (!frame) continue;
        CHECK(frame->index == i);
        CHECK(frame->features.motion2 == 0.0);
        const VmafV061Features features{frame->features.adm2, 0.0,
                                        frame->features.vif};
        CHECK_NEAR(frame->score, VmafV061Predict(features), 1e-9);
        expected_sum += frame->score;
    }
    CHECK(!sequence.Flush());
    const auto pooled = sequence.PooledScore();
    CHECK(pooled.has_value());
    if (pooled) CHECK_NEAR(*pooled, expected_sum / kFrames.size(), 1e-9);
    CHECK_THROWS_AS(sequence.Push(kFrames[0].spatial, 0.0), std::logic_error);
}
